async (page) => {
  const { execSync } = require('child_process');

  try {
    // Make the script executable
    execSync('chmod +x /tmp/mcp-workspace/backup_md.sh');
    console.log('✓ Script made executable');

    // Execute the backup script
    const output = execSync('/tmp/mcp-workspace/backup_md.sh', { encoding: 'utf-8' });
    console.log('\n=== BACKUP SCRIPT OUTPUT ===\n');
    console.log(output);

    return 'Backup script executed successfully';
  } catch (error) {
    console.error('Error:', error.message);
    return 'Error executing script';
  }
}
